// Input 1: rows from 'Read Current Queue' (all existing sheet rows)
// Webhook body available via $('Webhook Append').first().json.body
const body = $('Webhook Append').first().json.body || {};
const incoming = Array.isArray(body.rows) ? body.rows : [];

if (incoming.length === 0) {
  throw new Error('body.rows rỗng hoặc thiếu — cần mảng row theo schema queue');
}

// Tìm row_id lớn nhất hiện có để cấp id mới, tránh trùng
const existing = $input.all().map(item => item.json);
let maxId = 0;
for (const row of existing) {
  const id = parseInt(row.row_id, 10);
  if (!isNaN(id) && id > maxId) maxId = id;
}

const REQUIRED = ['lang', 'title', 'script', 'script_2'];
const out = [];
let nextId = maxId + 1;

for (const r of incoming) {
  const missing = REQUIRED.filter(f => !r[f]);
  if (missing.length > 0) {
    throw new Error(`Row thiếu field bắt buộc: ${missing.join(', ')} — title="${r.title || '(không có)'}"`);
  }
  if (r.lang !== 'vi' && r.lang !== 'en') {
    throw new Error(`lang phải là 'vi' hoặc 'en', nhận: ${r.lang}`);
  }

  out.push({
    json: {
      row_id: nextId++,
      status: 'review', // luôn ép cứng, không nhận từ client
      social: r.social || 'all',
      lang: r.lang,
      drive_file_id: '',
      cover_file_id: '',
      title: r.title,
      description: r.description || '',
      tags: r.tags || '',
      publish_at: r.publish_at || '',
      posted_at: '',
      script: r.script,
      script_2: r.script_2
    }
  });
}

return out;

const rows = $input.all().map(item => item.json);
return [{
  json: {
    ok: true,
    appended: rows.length,
    row_ids: rows.map(r => r.row_id)
  }
}];
